"use strict";
/**
 * Emit js/performance-data/{key}.js from existing data/{key}.json
 * (without re-parsing Excel). Used after a prior generate run.
 */
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const outJs = path.join(root, "js", "performance-data");
const keys = [
  "hf-live",
  "hf-backtest",
  "scalper-backtest",
  "swing-backtest",
  "scalper-live",
  "swing-live"
];

fs.mkdirSync(outJs, { recursive: true });

for (const key of keys) {
  const data = JSON.parse(
    fs.readFileSync(path.join(root, "data", key + ".json"), "utf8")
  );
  const jsPath = path.join(outJs, key + ".js");
  fs.writeFileSync(
    jsPath,
    "/* Generated by scripts/generate-performance-data.js — do not edit by hand */\n" +
      "(function(){\n" +
      '"use strict";\n' +
      "window.AIVOR_PERF_DATA = window.AIVOR_PERF_DATA || {};\n" +
      "window.AIVOR_PERF_DATA[" +
      JSON.stringify(key) +
      "] = " +
      JSON.stringify(data) +
      ";\n" +
      "})();\n"
  );
  const net = data.summary && data.summary.netProfit;
  console.log(
    "wrote",
    path.relative(root, jsPath),
    Math.round(fs.statSync(jsPath).size / 1024) + "KB",
    "available=" + data.available,
    net != null ? "net=" + net : ""
  );
}
